<script setup lang="ts">import {Database,Radio,Server,ShieldCheck} from "lucide-vue-next";import ProductPageLayout from "@/layouts/ProductPageLayout.vue";import {useRuntimeStore} from "@/stores/runtimeStore";const store=useRuntimeStore();const cards=[{label:"Core 服务",key:"coreOnline",icon:Server},{label:"PostgreSQL",key:"databaseConnected",icon:Database},{label:"OpenClaw 插件",key:"pluginLastSeen",icon:Radio},{label:"策略引擎",key:"policyVersion",icon:ShieldCheck}] as const;</script>
<template><ProductPageLayout eyebrow="运行状态" title="Core 状态" description="查看 TraceShield 控制平面的健康状态与数据接入遥测。"><section class="status-grid"><article v-for="card in cards" :key="card.key"><component :is="card.icon" :size="20"/><small>{{card.label}}</small><strong v-if="card.key==='coreOnline'">{{store.status.coreOnline?'在线':'离线'}}</strong><strong v-else-if="card.key==='databaseConnected'">{{store.status.databaseConnected?'已连接':'未连接'}}</strong><strong v-else>{{store.status[card.key]}}</strong></article></section><section class="telemetry"><header><div><small>运行时遥测</small><h2>控制平面详情</h2></div><span>数据源 · {{store.dataSource}}</span></header><dl><div><dt>已接收事件</dt><dd>{{store.status.eventsIngested.toLocaleString()}}</dd></div><div><dt>队列长度</dt><dd>{{store.status.queueSize}}</dd></div><div><dt>Core 版本</dt><dd>{{store.status.coreVersion}}</dd></div><div><dt>策略版本</dt><dd>{{store.status.policyVersion}}</dd></div></dl></section></ProductPageLayout></template>
<style scoped>.status-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:11px}.status-grid article{display:grid;grid-template-columns:32px 1fr;gap:1px 10px;padding:16px;border:1px solid var(--trace-border);border-radius:14px;background:#fff;box-shadow:0 8px 22px rgba(30,41,59,.04)}.status-grid article>svg{grid-row:1/3;align-self:center;color:var(--trace-red)}.status-grid small{color:#8993a1;font-size:8px}.status-grid strong{font:650 12px var(--trace-font-mono)}.telemetry{margin-top:13px;padding:18px;border:1px solid var(--trace-border);border-radius:15px;background:#fff}.telemetry header{display:flex;align-items:end;justify-content:space-between}.telemetry header small{color:var(--trace-red);font-size:8px;text-transform:uppercase}.telemetry h2{margin:4px 0;font-size:16px}.telemetry header span{color:#8b95a2;font-size:8px}.telemetry dl{display:grid;grid-template-columns:1fr 1fr;margin:17px 0 0;border:1px solid #e7eaed;border-radius:10px;overflow:hidden}.telemetry dl div{display:flex;justify-content:space-between;padding:13px;border-bottom:1px solid #edf0f2;background:#fafbfb;font-size:9px}.telemetry dt{color:#7b8695}.telemetry dd{margin:0;font:650 9px var(--trace-font-mono)}</style>
